package com.tilelayers;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;

import static net.runelite.api.MenuAction.MENU_ACTION_DEPRIORITIZE_OFFSET;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

import java.util.*;

@PluginDescriptor(
		name = "Tile Layers",
		description = "Draw overlays beneath players and NPCs, with adjustable opacity and a nearest-character limit.",
		tags = {"overlay", "tile", "indicators"}
)
@Slf4j
public class TileLayersPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TileLayersOverlay overlay;

	@Inject TileLayersConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private RenderedActors renderedActors;

	@Getter(AccessLevel.PACKAGE)
	private final Set<NPC> onTopNpcs = Collections.newSetFromMap(new IdentityHashMap<>());
	private List<String> onTopNPCNames = new ArrayList<>();

	@Getter(AccessLevel.PACKAGE)
	private final NearestActors nearestActors = new NearestActors();

	@Getter(AccessLevel.PACKAGE)
	private final ActorMaskAdmission actorMaskAdmission = new ActorMaskAdmission();
	private final OverlayMaskOrder overlayMaskOrder = new OverlayMaskOrder();
	private volatile boolean started;

	private static final String ADD_NPC_NAME = "Add NPC name";
	private static final String REMOVE_NPC_NAME = "Remove NPC name";
	private static final String UNTAG_ALL = "Un-tag-All";

	@Provides
	TileLayersConfig provideConfig(ConfigManager configManager)
	{
		migrateCharacterLimit(configManager);
		return configManager.getConfig(TileLayersConfig.class);
	}

	@Override
	protected void startUp()
	{
		started = true;
		resetActors();
		renderCallbackManager.register(renderedActors);
		overlayManager.add(overlay);
		clientThread.invoke(() -> {
			if (!started) return;
			updateOverlayOrder();
			rebuild();
		});
	}

	@Override
	protected void shutDown()
	{
		synchronized (overlayManager)
		{
			started = false;
			overlayMaskOrder.restore();
			// Removing our overlay also rebuilds the restored draw order.
			overlayManager.remove(overlay);
		}
		renderCallbackManager.unregister(renderedActors);
		resetActors();
		onTopNpcs.clear();
		// Dispose graphics resources on the thread that paints the masks.
		clientThread.invoke(overlay::release);
	}

	private void updateOverlayOrder()
	{
		synchronized (overlayManager)
		{
			if (!started || !overlayMaskOrder.update(overlayManager, config.keepLootAboveCharacters(), config.onlyTileAndMarkerPlugins())) return;
			// Priority setters do not re-sort RuneLite's overlay lists. Re-add
			// only our overlay to rebuild them without saving other plugin settings.
			overlayManager.remove(overlay);
			overlayManager.add(overlay);
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		clientThread.invoke(this::updateOverlayOrder);
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invoke(this::updateOverlayOrder);
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		// Also catch scene overlays added during gameplay after plugin startup.
		if (config.onlyTileAndMarkerPlugins() || config.keepLootAboveCharacters())
		{
			synchronized (overlayManager)
			{
				if (started && overlayMaskOrder.needsUpdate(overlayManager, config.keepLootAboveCharacters(), config.onlyTileAndMarkerPlugins())) updateOverlayOrder();
			}
		}
		nearestActors.setExcludedNpcs(config.excludedBosses());
		boolean enabled = client.isGpu() && config.overlayOpacity() < 100;
		Player local = client.getLocalPlayer();
		boolean otherPlayers = enabled && config.overlaysBelowOtherPlayers();
		boolean allNpcs = enabled && config.overlaysBelowAllNPCs();
		boolean namedNpcs = enabled && config.overlaysBelowNPCs() && !onTopNpcs.isEmpty();
		if (otherPlayers || allNpcs || namedNpcs)
		{
			nearestActors.select(local, namedNpcs ? onTopNpcs : Collections.emptySet(),
					otherPlayers || allNpcs ? client.getTopLevelWorldView() : null,
					otherPlayers, allNpcs, config.characterLimit());
		}
		else nearestActors.clear();
		actorMaskAdmission.beginFrame(nearestActors);
		renderedActors.beginFrame(enabled && config.overlaysBelowPlayer() ? local : null, nearestActors.selected());
	}

	private void resetActors()
	{
		nearestActors.clear();
		actorMaskAdmission.clear();
		renderedActors.beginFrame(null, Collections.emptySet());
	}

	private static void migrateCharacterLimit(ConfigManager configManager)
	{
		// The old threshold has a different meaning. Preserve an explicit disabled
		// setting, but use the new default instead of treating 80 as a nearest cap.
		// Do this when providing the config, before RuneLite writes new defaults.
		if (configManager.getConfiguration("improvedtileindicators", "characterLimit") == null
				&& "0".equals(configManager.getConfiguration("improvedtileindicators", "crowdLimit")))
		{
			configManager.setConfiguration("improvedtileindicators", "characterLimit", 0);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN) resetActors();
		if (event.getGameState() == GameState.LOGIN_SCREEN ||
				event.getGameState() == GameState.HOPPING)
		{
			onTopNpcs.clear();
		}
		else if (event.getGameState() == GameState.LOGGED_IN) rebuild();
	}

	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		clientThread.invoke(this::rebuild);
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		WorldView world = event.getWorldView();
		clientThread.invoke(() -> {
			resetActors();
			onTopNpcs.removeIf(npc -> npc.getWorldView() == null || npc.getWorldView() == world);
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!configChanged.getGroup().equals("improvedtileindicators"))
		{
			return;
		}

		clientThread.invoke(() -> {
			if (!started) return;
			updateOverlayOrder();
			rebuild();
		});
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned)
	{
		final NPC npc = npcSpawned.getNpc();
		final String npcName = npc.getName();

		if (npcName == null)
		{
			return;
		}

		if (onTopMatchesNPCName(npcName))
		{
			onTopNpcs.add(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned npcDespawned)
	{
		final NPC npc = npcDespawned.getNpc();
		onTopNpcs.remove(npc);
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		String name = npc.getName();
		if (name != null && onTopMatchesNPCName(name)) onTopNpcs.add(npc);
		else onTopNpcs.remove(npc);
	}


	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		int type = event.getType();

		if (type >= MENU_ACTION_DEPRIORITIZE_OFFSET)
		{
			type -= MENU_ACTION_DEPRIORITIZE_OFFSET;
		}

		final MenuAction menuAction = MenuAction.of(type);

		if (menuAction == MenuAction.EXAMINE_NPC && client.isKeyPressed(KeyCode.KC_SHIFT) && config.overlaysBelowNPCs())
		{
			final int worldViewId = event.getMenuEntry().getWorldViewId();
			final String npcName = getNameForCachedNPC(event.getIdentifier(), worldViewId);
			if (npcName == null) return;
			boolean matchesList = onTopNPCNames.stream()
					.filter(highlight -> !highlight.equalsIgnoreCase(npcName))
					.anyMatch(highlight -> WildcardMatcher.matches(highlight, npcName));

			// Wildcard entries must be edited in the name box, not removed by an exact-name menu action.
			if (!matchesList)
			{
				client.createMenuEntry(-1)
					.setOption(onTopNPCNames.stream().anyMatch(npcName::equalsIgnoreCase) ? REMOVE_NPC_NAME : ADD_NPC_NAME)
					.setTarget(event.getTarget())
					.setIdentifier(event.getIdentifier())
					.setWorldViewId(worldViewId)
					.setType(MenuAction.RUNELITE)
					.onClick(this::toggleDraw);
			}
		}
	}

	public void toggleDraw(MenuEntry click)
	{
		final String name = getNameForCachedNPC(click.getIdentifier(), click.getWorldViewId());
		if (name == null) return;
		// this trips a config change which triggers the overlay rebuild
		updateNpcsToDrawAbove(name);
	}

	private void updateNpcsToDrawAbove(String npc)
	{
		final List<String> highlightedNpcs = new ArrayList<>(onTopNPCNames);

		if (!highlightedNpcs.removeIf(npc::equalsIgnoreCase))
		{
			highlightedNpcs.add(npc);
		}

		// this triggers the config change event and rebuilds npcs
		config.setTopNPCs(Text.toCSV(highlightedNpcs));
	}

	List<String> getTopNPCs()
	{
		final String configNpcs = config.getTopNPCs();

		if (configNpcs == null || configNpcs.trim().isEmpty())
		{
			return Collections.emptyList();
		}

		List<String> names = new ArrayList<>();
		for (String name : Text.fromCSV(configNpcs))
		{
			String trimmed = name.trim();
			if (!trimmed.isEmpty()) names.add(trimmed);
		}
		return names;
	}

	void rebuild()
	{
		onTopNPCNames = getTopNPCs();
		onTopNpcs.clear();

		if (client.getGameState() != GameState.LOGGED_IN &&
				client.getGameState() != GameState.LOADING)
		{
			return;
		}

		rebuildWorld(client.getTopLevelWorldView());
	}

	private void rebuildWorld(WorldView world)
	{
		if (world == null) return;
		for (NPC npc : world.npcs())
		{
			if (npc == null) continue;
			final String npcName = npc.getName();

			if (npcName == null)
			{
				continue;
			}

			if (onTopMatchesNPCName(npcName))
			{
				onTopNpcs.add(npc);
			}
		}
		for (WorldView child : world.worldViews()) rebuildWorld(child);
	}

	private boolean onTopMatchesNPCName(String npcName)
	{
		for (String matching : onTopNPCNames)
		{
			if (WildcardMatcher.matches(matching, npcName))
			{
				return true;
			}
		}

		return false;
	}

	private String getNameForCachedNPC(int id, int worldViewId)
	{
		final WorldView world = client.getWorldView(worldViewId);
		if (world == null) return null;
		final NPC npc = world.npcs().byIndex(id);

		if (npc == null)
		{
			return null;
		}

		return npc.getName();
	}

}

